/** Removes the single session that owns this token hash; unknown hashes are a no-op. */
export async function revokeSessionByTokenHash(
  tokenHash: string,
): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.tokenHash, tokenHash)).run();
}

/** Ends every session of one account and leaves other accounts untouched. */
export async function revokeUserSessions(userId: UserId): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.userId, userId)).run();
}

/**
 * Housekeeping sweep; returns how many rows it removed. Only sessions whose
 * own expiry has passed are removed — live sessions are never touched.
 */
export async function purgeExpiredSessions(
  now: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lt(sessions.expiresAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

