/** Buckets guarding the unauthenticated endpoints, keyed per address. */
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";

/**
 * Rate limiting before a session exists has no tenant to charge against, so
 * every unauthenticated attempt is billed to this sentinel org; the address
 * is carried in the bucket key so one account never throttles another.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/** How long a password-reset link stays usable after it is sent. */
const RESET_TTL_MS = 60 * 60 * 1000;

function addressBucket(bucket: string, email: string): string {
  return `${bucket}:${email.toLowerCase()}`;
}

